CREATE OR REPLACE FUNCTION app.current_tools()
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT COALESCE(array_agg(g.tool ORDER BY g.tool),'{}')
